package de.eldoria.bloodnight.generated;

import de.eldoria.bloodnight.api.CompiledBehaviour;
import de.eldoria.bloodnight.api.MobContext;
import de.eldoria.bloodnight.graph.runtime.Registries;
import de.eldoria.graph.std.runtime.Cooldown;
import de.eldoria.graph.std.runtime.TimeUnit;
import io.papermc.paper.registry.RegistryKey;
import org.bukkit.entity.Creeper;
import org.bukkit.event.entity.ExplosionPrimeEvent;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;

public final class SpeedCreeperBehaviour implements CompiledBehaviour {
    private static final TimeUnit MILLISECONDS = TimeUnit.MILLISECONDS;

    private static final PotionEffectType SPEED = Registries.entry(RegistryKey.MOB_EFFECT, "minecraft:speed");

    private final MobContext context;

    private Cooldown cooldown;

    public SpeedCreeperBehaviour(MobContext context) {
        this.context = context;
        // node #24 function.cooldown
        this.cooldown = new Cooldown();
    }

    @Override
    public void onExplosionPrime(ExplosionPrimeEvent event) {
        // node #3 event.explosion_prime
        // node #4 event_data.explosion_prime.mutate
        event.setFire(true);
        // node #5
    }

    @Override
    public void onNightEnd() {
        // node #11 mob.night_end
        // node #13 creeper.mutate
        // node #12 mob.self
        final Creeper self = ((Creeper) this.context.entity());
        self.setMaxFuseTicks(0);
        // node #14 creeper.ignite
        self.ignite();
        // node #15
    }

    @Override
    public void onSpawn() {
        // node #20 mob.spawn
        // node #21 creeper.mutate
        ((Creeper) this.context.entity()).setMaxFuseTicks(10);
        // node #22
    }

    @Override
    public void onTick() {
        // node #30 mob.tick
        // node #33 flow.branch
        // node #31 function.cooldown
        final boolean cooldown = this.cooldown.ready(MILLISECONDS.toMillis(30000.0d));
        if (!cooldown) return;
        // node #32 living_entity.apply_effect
        ((Creeper) this.context.entity()).addPotionEffect(new PotionEffect(SPEED, (int) (60.0d * 20), 4, true, true));
        // node #34
    }
}
